29	public abstract class NullableSingleInputAggregationFunction<I, F extends Comparable>
30	    extends BaseSingleInputAggregationFunction<I, F> {
31	  protected final boolean _nullHandlingEnabled;
32	
33	  public NullableSingleInputAggregationFunction(ExpressionContext expression, boolean nullHandlingEnabled) {
34	    super(expression);
35	    _nullHandlingEnabled = nullHandlingEnabled;
36	  }
