38	  /**
39	   * A consumer that is being used to consume batch of indexes.
40	   */
41	  @FunctionalInterface
42	  public interface BatchConsumer {
43	    /**
44	     * Consumes a batch of indexes.
45	     * @param fromInclusive the start index (inclusive)
46	     * @param toExclusive the end index (exclusive)
47	     */
48	    void consume(int fromInclusive, int toExclusive);
49	  }
50	
51	  /**
52	   * A reducer that is being used to fold over consecutive indexes.
53	   * @param <A>
54	   */
55	  @FunctionalInterface
56	  public interface Reducer<A> {
57	    /**
58	     * Applies the reducer to the range of indexes.
59	     * @param acum the initial value of the accumulator
60	     * @param fromInclusive the start index (inclusive)
61	     * @param toExclusive the end index (exclusive)
62	     * @return the next value of the accumulator (maybe the same as the input)
63	     */
64	    A apply(A acum, int fromInclusive, int toExclusive);
65	  }
66	
67	  /**
68	   * Iterates over the non-null ranges of the blockValSet and calls the consumer for each range.
69	   * @param blockValSet the blockValSet to iterate over
70	   * @param consumer the consumer to call for each non-null range
71	   */
72	  public void forEachNotNull(int length, BlockValSet blockValSet, BatchConsumer consumer) {
73	    if (!_nullHandlingEnabled) {
74	      consumer.consume(0, length);
75	      return;
76	    }
77	
78	    RoaringBitmap roaringBitmap = blockValSet.getNullBitmap();
79	    if (roaringBitmap == null) {
80	      consumer.consume(0, length);
81	      return;
82	    }
83	
84	    // Skip if entire block is null
85	    if (!roaringBitmap.contains(0, length)) {
86	      forEachNotNull(length, roaringBitmap.getIntIterator(), consumer);
87	    }
88	  }
