90	  /**
91	   * Iterates over the non-null ranges of the nullIndexIterator and calls the consumer for each range.
92	   * @param nullIndexIterator an int iterator that returns values in ascending order whose min value is 0.
93	   *                          Rows are considered null if and only if their index is emitted.
94	   */
95	  public void forEachNotNull(int length, IntIterator nullIndexIterator, BatchConsumer consumer) {
96	    int prev = 0;
97	    while (nullIndexIterator.hasNext() && prev < length) {
98	      int nextNull = Math.min(nullIndexIterator.next(), length);
99	      if (nextNull > prev) {
100	        consumer.consume(prev, nextNull);
101	      }
102	      prev = nextNull + 1;
103	    }
104	    if (prev < length) {
105	      consumer.consume(prev, length);
106	    }
107	  }
