141	   * @param <A> The type of the accumulator
142	   */
143	  public <A> A foldNotNull(int length, @Nullable IntIterator nullIndexIterator, A initialAcum, Reducer<A> reducer) {
144	    A acum = initialAcum;
145	
146	    if (length == 0) {
147	      return acum;
148	    }
149	
150	    if (!_nullHandlingEnabled || nullIndexIterator == null || !nullIndexIterator.hasNext()) {
151	      return reducer.apply(initialAcum, 0, length);
152	    }
153	
154	    int prev = 0;
155	    while (nullIndexIterator.hasNext() && prev < length) {
156	      int nextNull = Math.min(nullIndexIterator.next(), length);
157	      if (nextNull > prev) {
158	        acum = reducer.apply(acum, prev, nextNull);
159	      }
160	      prev = nextNull + 1;
161	    }
162	    if (prev < length) {
163	      acum = reducer.apply(acum, prev, length);
164	    }
165	    return acum;
166	  }
