/**
 * Sum aggregation function specialized for integer (INT/LONG) columns. Unlike {@link SumAggregationFunction} it keeps
 * the running sum as a {@code long}, so integer values are never converted to floating-point numbers and no precision
 * is lost.
 */
public class SumIntAggregationFunction extends NullableSingleInputAggregationFunction<Long, Long> {
  protected static final long DEFAULT_VALUE = 0L;

  public SumIntAggregationFunction(List<ExpressionContext> arguments, boolean nullHandlingEnabled) {
    this(verifySingleArgument(arguments, "SUMINT"), nullHandlingEnabled);
  }

  protected SumIntAggregationFunction(ExpressionContext expression, boolean nullHandlingEnabled) {
    super(expression, nullHandlingEnabled);
  }

  @Override
  public AggregationFunctionType getType() {
    return AggregationFunctionType.SUMINT;
  }

  @Override
  public AggregationResultHolder createAggregationResultHolder() {
    return new ObjectAggregationResultHolder();
  }

  @Override
  public GroupByResultHolder createGroupByResultHolder(int initialCapacity, int maxCapacity) {
    return new ObjectGroupByResultHolder(initialCapacity, maxCapacity);
  }

  @Override
  public void aggregate(int length, AggregationResultHolder aggregationResultHolder,
      Map<ExpressionContext, BlockValSet> blockValSetMap) {
    BlockValSet blockValSet = blockValSetMap.get(_expression);

    Long sum;
    switch (blockValSet.getValueType().getStoredType()) {
      case INT: {
        int[] values = blockValSet.getIntValuesSV();

        sum = foldNotNull(length, blockValSet, null, (acum, from, to) -> {
          long innerSum = 0;
          for (int i = from; i < to; i++) {
            innerSum += values[i];
          }
          return acum == null ? innerSum : acum + innerSum;
        });

        break;
      }
      case LONG: {
        long[] values = blockValSet.getLongValuesSV();

        sum = foldNotNull(length, blockValSet, null, (acum, from, to) -> {
          long innerSum = 0;
          for (int i = from; i < to; i++) {
            innerSum += values[i];
          }
          return acum == null ? innerSum : acum + innerSum;
        });

        break;
      }
      default:
        throw new BadQueryRequestException(
            "Cannot compute sumInt for non-integer type: " + blockValSet.getValueType());
    }
    updateAggregationResultHolder(aggregationResultHolder, sum);
  }

  protected void updateAggregationResultHolder(AggregationResultHolder aggregationResultHolder, Long sum) {
    if (sum != null) {
      Long otherSum = aggregationResultHolder.getResult();
      aggregationResultHolder.setValue(otherSum == null ? sum : sum + otherSum);
    }
  }

  @Override
  public void aggregateGroupBySV(int length, int[] groupKeyArray, GroupByResultHolder groupByResultHolder,
      Map<ExpressionContext, BlockValSet> blockValSetMap) {
    BlockValSet blockValSet = blockValSetMap.get(_expression);
    long[] valueArray = blockValSet.getLongValuesSV();

    forEachNotNull(length, blockValSet, (from, to) -> {
      for (int i = from; i < to; i++) {
        int groupKey = groupKeyArray[i];
        Long result = groupByResultHolder.getResult(groupKey);
        groupByResultHolder.setValueForKey(groupKey, result == null ? valueArray[i] : result + valueArray[i]);
      }
    });
  }

  @Override
  public void aggregateGroupByMV(int length, int[][] groupKeysArray, GroupByResultHolder groupByResultHolder,
      Map<ExpressionContext, BlockValSet> blockValSetMap) {
    BlockValSet blockValSet = blockValSetMap.get(_expression);
    long[] valueArray = blockValSet.getLongValuesSV();

    forEachNotNull(length, blockValSet, (from, to) -> {
      for (int i = from; i < to; i++) {
        long value = valueArray[i];
        for (int groupKey : groupKeysArray[i]) {
          Long result = groupByResultHolder.getResult(groupKey);
          groupByResultHolder.setValueForKey(groupKey, result == null ? value : result + value);
        }
      }
    });
  }

  @Override
  public Long extractAggregationResult(AggregationResultHolder aggregationResultHolder) {
    Long result = aggregationResultHolder.getResult();
    if (_nullHandlingEnabled) {
      return result;
    }
    return result == null ? DEFAULT_VALUE : result;
  }

  @Override
  public Long extractGroupByResult(GroupByResultHolder groupByResultHolder, int groupKey) {
    Long result = groupByResultHolder.getResult(groupKey);
    if (_nullHandlingEnabled) {
      return result;
    }
    return result == null ? DEFAULT_VALUE : result;
  }

  @Override
  public Long merge(Long intermediateResult1, Long intermediateResult2) {
    if (_nullHandlingEnabled) {
      if (intermediateResult1 == null) {
        return intermediateResult2;
      }
      if (intermediateResult2 == null) {
        return intermediateResult1;
      }
    }
    return intermediateResult1 + intermediateResult2;
  }

  @Override
  public ColumnDataType getIntermediateResultColumnType() {
    return ColumnDataType.LONG;
  }

  @Override
  public ColumnDataType getFinalResultColumnType() {
    return ColumnDataType.LONG;
  }

  @Override
  public Long extractFinalResult(Long intermediateResult) {
    return intermediateResult;
  }

  @Override
  public Long mergeFinalResult(Long finalResult1, Long finalResult2) {
    return merge(finalResult1, finalResult2);
  }
}
